cards.content:
{% set lademodus = is_state('switch.spot_charge_scheduler_lademodus_aktiv', 'on') %}
{% if lademodus %}🔌 **Lademodus AKTIV** — steuert `switch.model_3_charger`{% else %}⏸️ **Lademodus AUS** — steuert nichts, sammelt nur Kalibrierungsdaten{% endif %}
{% set plan_status = states('sensor.spot_charge_scheduler_ladeplan') %}
{% set status_map = {'kein_ziel': '⚪ Kein Ziel gesetzt', 'ziel_erreicht': '🟢 Ziel erreicht', 'nicht_zuhause': '🅿️ Fahrzeug nicht zuhause — wartet', 'erreichbar': '🟡 Plant günstige Slots (Ziel erreichbar)', 'nicht_erreichbar': '🔴 Zeit knapp — lädt durchgehend, koste es was es wolle'} %}
<br>{{ status_map.get(plan_status, plan_status) }}
{% set aktiv = state_attr('sensor.spot_charge_scheduler_ladeplan', 'aktiver_zyklus') %}
{% if aktiv %}<br>Aktiver Zyklus: {{ aktiv }}{% endif %}
{% set kosten = state_attr('sensor.spot_charge_scheduler_ladeplan', 'geschaetzte_kosten_eur') %}
{% set fertig = state_attr('sensor.spot_charge_scheduler_ladeplan', 'geschaetzte_fertigstellung') %}
{% set slots = state_attr('sensor.spot_charge_scheduler_ladeplan', 'naechste_slots') or [] %}
{% if kosten is not none %}
<br>Geschätzte Kosten: {{ kosten }} € · Fertig ca. {{ (fertig | as_datetime | as_local).strftime('%d.%m. %H:%M') if fertig else '—' }} · {{ slots | length }} Slot(s) geplant
{% endif %}
{% set kalib = states('sensor.spot_charge_scheduler_kalibrierte_kapazitat') %}
{% set samples = state_attr('sensor.spot_charge_scheduler_kalibrierte_kapazitat', 'anzahl_ladevorgaenge') | default(0, true) %}
<br>Akkukapazität: {{ kalib }} kWh ({{ samples }} Ladevorgänge kalibriert)

{% set slots = state_attr('sensor.spot_charge_scheduler_ladeplan', 'naechste_slots') or [] %}
{% if slots %}
{% for s in slots[:10] %}- {{ (s.start | as_datetime | as_local).strftime('%a %d.%m. %H:%M') }} · {{ '%.3f' | format(s.preis_eur_kwh) }} €/kWh
{% endfor %}
{% if slots | length > 10 %}
… und {{ slots | length - 10 }} weitere
{% endif %}
{% else %}
_Keine Slots geplant — entweder kein Ziel gesetzt, Ziel schon erreicht, oder noch keine Preisdaten verfügbar._
{% endif %}
